package com.aytronn.hermesbridge.service.audio;

import java.util.Base64;

/**
 * An original, low-volume waiting loop generated from two sine waves with FFmpeg.
 * It contains no third-party recording and is only emitted while Hermes is preparing speech.
 */
final class SilenceMp3 {
  private SilenceMp3() { }

  static final byte[] SEGMENT = Base64.getDecoder().decode(
      "");
}
